#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    cin >> s;

    for (char c = 'a'; c <= 'z'; ++c) {
        bool found = false;
        for (size_t j = 0; j + 1 < s.size(); ++j) {
            if (s[j] == c) {
                found = true;
                break;
            }
        }

        if (!found) {
            cout << (c == s.back() ? "YES" : "NO");
            return 0;
        }
    }

    cout << "NO";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    cin >> s;

    bool seen[26] = {};
    for (size_t i = 0; i + 1 < s.size(); ++i) {
        if (s[i] >= 'a' && s[i] <= 'z')
            seen[s[i] - 'a'] = true;
    }

    char missing = 'a';
    while (missing <= 'z' && seen[missing - 'a'])
        ++missing;

    cout << (!s.empty() && missing <= 'z' && missing == s.back() ? "YES" : "NO");
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    cin >> s;

    bool present[26] = {};
    for (size_t j = 0; j + 1 < s.size(); ++j) {
        if (s[j] >= 'a' && s[j] <= 'z')
            present[s[j] - 'a'] = true;
    }

    char missing = '{';
    for (int i = 0; i < 26; ++i) {
        if (!present[i]) {
            missing = static_cast<char>('a' + i);
            break;
        }
    }

    cout << (!s.empty() && missing == s.back() ? "YES" : "NO");
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    cin >> s;

    vector<bool> seen(26, false);
    for (size_t i = 0; i + 1 < s.size(); ++i) {
        seen[s[i] - 'a'] = true;
    }

    for (int i = 0; i < 26; ++i) {
        if (!seen[i]) {
            cout << (s.back() == 'a' + i ? "YES" : "NO");
            return 0;
        }
    }

    cout << "NO";
    return 0;
}

